// Ring modulator: Two actual oscillator primitives feed the carrier and modulator audio ports.
// Audition composition of public Rust primitives; not an instrument parity claim.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  oscillator as oscillatorDefinition,
  ringModulator as ringModulatorDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    low_waveform: {
      "path": "/primitives/ring/low/0",
      "label": "Waveform",
      "group": "Oscillator",
      "min": 0,
      "max": 4,
      "default": 0,
      "choices": [
        "Sine",
        "Saw",
        "Square",
        "Triangle",
        "Blend"
      ]
    },
    low_frequency: {
      "path": "/primitives/ring/low/1",
      "label": "Frequency",
      "group": "Oscillator",
      "min": 20,
      "max": 16000,
      "default": 110
    },
    low_level: {
      "path": "/primitives/ring/low/2",
      "label": "Level",
      "group": "Oscillator",
      "min": 0,
      "max": 1,
      "default": 0.16
    },
    high_waveform: {
      "path": "/primitives/ring/high/0",
      "label": "Waveform",
      "group": "Oscillator",
      "min": 0,
      "max": 4,
      "default": 1,
      "choices": [
        "Sine",
        "Saw",
        "Square",
        "Triangle",
        "Blend"
      ]
    },
    high_frequency: {
      "path": "/primitives/ring/high/1",
      "label": "Frequency",
      "group": "Oscillator",
      "min": 20,
      "max": 16000,
      "default": 330
    },
    high_level: {
      "path": "/primitives/ring/high/2",
      "label": "Level",
      "group": "Oscillator",
      "min": 0,
      "max": 1,
      "default": 0.16
    },
    ring_carrierHz: {
      "path": "/primitives/ring/ring/0",
      "label": "Carrier Hz",
      "group": "Ring modulator",
      "min": 0.1,
      "max": 8000,
      "default": 180
    },
    ring_depth: {
      "path": "/primitives/ring/ring/1",
      "label": "Depth",
      "group": "Ring modulator",
      "min": 0,
      "max": 1,
      "default": 1
    },
    ring_wetMix: {
      "path": "/primitives/ring/ring/2",
      "label": "Wet mix",
      "group": "Ring modulator",
      "min": 0,
      "max": 1,
      "default": 1
    },
    ring_spread: {
      "path": "/primitives/ring/ring/3",
      "label": "Spread",
      "group": "Ring modulator",
      "min": 0,
      "max": 180,
      "default": 0
    },
    ring_enabled: {
      "path": "/primitives/ring/ring/4",
      "label": "Enabled",
      "group": "Ring modulator",
      "min": 0,
      "max": 1,
      "default": 1,
      "choices": [
        "Off",
        "On"
      ]
    },
  };

  // Audio inputs and outputs — generated sound; no audio input is needed.
  const graph = createGraphWorkspace().setInputSource('none');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const low = graph.add(oscillatorDefinition.type, {"id":4});
  graph.registerInstance('/primitives/ring/low', low);
  low.parameter('waveform').expose(controls.low_waveform);
  low.parameter('frequency').expose(controls.low_frequency);
  low.parameter('level').expose(controls.low_level);

  const high = graph.add(oscillatorDefinition.type, {"id":5});
  graph.registerInstance('/primitives/ring/high', high);
  high.parameter('waveform').expose(controls.high_waveform);
  high.parameter('frequency').expose(controls.high_frequency);
  high.parameter('level').expose(controls.high_level);

  const ring = graph.add(ringModulatorDefinition.type, {"id":6});
  graph.registerInstance('/primitives/ring/ring', ring);
  ring.parameter('carrierHz').expose(controls.ring_carrierHz);
  ring.parameter('depth').expose(controls.ring_depth);
  ring.parameter('wetMix').expose(controls.ring_wetMix);
  ring.parameter('spread').expose(controls.ring_spread);
  ring.parameter('enabled').expose(controls.ring_enabled);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(low.output('out'), ring.input('carrier'));
  graph.connect(high.output('out'), ring.input('modulator'));
  graph.connect(ring.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.low_waveform,
    controls.low_frequency,
    controls.low_level,
    controls.high_waveform,
    controls.high_frequency,
    controls.high_level,
    controls.ring_carrierHz,
    controls.ring_depth,
    controls.ring_wetMix,
    controls.ring_spread,
    controls.ring_enabled
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
